INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C1','kor',2,1,'u4',1,'여러 가지 방법으로 시 읽기 — 「누가 누가 잠자나」를 자장가 같은 분위기를 살려 주고받으며·손뼉 치며·몸짓하며 읽고, 떠오르는 생각이나 느낌 나누기',ARRAY['2국05-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C2','kor',2,1,'u4',1,'시 속 겹받침 낱말 바르게 읽기 — 넓고 넓은[널꼬 널븐]·모여 앉아[모여 안자]처럼 소리와 표기가 다른 낱말을 바르게 소리 내기',ARRAY['2국04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C3','kor',2,1,'u4',3,'겹받침과 쌍받침 — 받침이 있는지·받침 자음자 개수·받침 종류로 낱말을 나누고, 같은 자음자 둘(ㄲ·ㅆ)은 쌍받침, 다른 자음자 둘(ㄳ·ㄵ·ㄶ·ㄼ 등)은 겹받침임을 알기',ARRAY['2국04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C4','kor',2,1,'u4',3,'겹받침 낱말의 뜻과 바른 쓰기 — 밟다·값·끊다·얹다·맑다·몫 등의 뜻을 알고, 소리 나는 대로가 아니라 바른 표기로 문장에 쓰기',ARRAY['2국04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C5','kor',2,1,'u4',3,'겹받침 발음 규칙 — ㄳ은 ㄱ, ㄵ·ㄶ은 ㄴ, ㅄ은 ㅂ처럼 대부분 앞 받침 하나만 소리 나고, 「다」가 붙으면 [따]·[타]로 소리 남을 찾아 놀이로 익히기',ARRAY['2국04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C6','kor',2,1,'u4',6,'「바다에 쓰레기가 모여 있다고?」 내용과 낱말 — 플라스틱 쓰레기 더미가 생기는 까닭, 환경 단체와 우리의 노력, 더미·부표·분류의 뜻 알기',ARRAY['2국02-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C7','kor',2,1,'u4',6,'받침과 띄어 읽기에 주의하며 글 읽기 — 많은[마는]·없애기도[업쌔기도]·몫[목]을 바르게 읽고, 뜻 덩어리마다 알맞게 띄어 짝과 번갈아 읽으며 점검하기',ARRAY['2국02-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C8','kor',2,1,'u4',8,'「바람은 착하지」 내용 — 바람이 신문지를 끌고 골목으로 나가 그늘에서 떠는 어린 민들레꽃에게 목도리를 해 주고 「힘내렴!」 하고 떠나는 장면 파악하기',ARRAY['2국05-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C9','kor',2,1,'u4',8,'시의 분위기 파악하기 — 떠오르는 장면을 몸짓·그림으로 나타내고 바람·신문지·민들레꽃의 마음과 내 경험을 떠올려 따뜻한·당당한 분위기를 찾고 서로의 생각 나누기',ARRAY['2국05-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C10','kor',2,1,'u4',10,'「오늘」을 분위기에 알맞게 읽기 — 좋은 일이 많을 거라 한 까닭과 「나」의 즐거운 마음을 찾고, 밝고 힘찬 목소리·알맞은 빠르기로 소리 내어 읽기',ARRAY['2국05-01']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C11','kor',2,1,'u4',10,'내 경험으로 시 바꾸어 쓰기 — 시 속 인물에게 하고 싶은 말을 떠올리고, 기분 좋았던 내 경험으로 시의 한 부분을 분위기를 살려 바꾸어 쓰고 함께 읽기',ARRAY['2국05-01']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C12','kor',2,1,'u4',12,'좋아하는 시 낭송하기 — 시집에서 마음에 드는 시를 골라 옮겨 쓰고, 내용에 어울리는 목소리·장면·인물의 마음을 살려 낭송하며 친구의 낭송을 칭찬하며 듣기',ARRAY['2국05-01']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C13','kor',2,1,'u4',12,'겹받침 정리와 토박이말 — 품삯·괜찮다·가엾다 등 바른 발음 고르기, 볼가심·나들목·마루·해거름 같은 토박이말의 뜻 알고 문장에 쓰기(정리·기초 다지기)',ARRAY['2국04-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X01','kor',2,'u4',ARRAY['K2-1-u4-C2','K2-1-u4-C5','K2-1-u4-C13']::text[],'겹받침의 두 받침을 모두 소리 내거나 엉뚱한 받침을 소리 낸다(흙 → [흘ㄱ], 값 → [갓])','대부분 앞 받침 하나만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X02','kor',2,'u4',ARRAY['K2-1-u4-C4','K2-1-u4-C13']::text[],'겹받침 낱말을 소리 나는 대로 적는다(많은 → 마는, 앉았다 → 안잤다)','소리와 표기는 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X03','kor',2,'u4',ARRAY['K2-1-u4-C3']::text[],'쌍받침과 겹받침을 헷갈린다','같은 자음자 둘? 다른 자음자 둘?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X04','kor',2,'u4',ARRAY['K2-1-u4-C2','K2-1-u4-C5','K2-1-u4-C7']::text[],'겹받침 뒤 「다」를 그대로 읽거나 받침이 뒤로 넘어가는 소리를 놓친다(앉다 → [안다], 앉아 → [안아])','[따]·[타], 뒤로 넘기기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X05','kor',2,'u4',ARRAY['K2-1-u4-C4','K2-1-u4-C6']::text[],'낱말의 뜻을 헷갈려 엉뚱한 자리에 쓴다(얹다↔앉다, 부표↔더미)','문장에 넣어 장면 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X06','kor',2,'u4',ARRAY['K2-1-u4-C6','K2-1-u4-C8','K2-1-u4-C10']::text[],'글이나 시에 없는 내용으로 답하거나 내용을 바꿔 안다','그 부분을 글에서 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X07','kor',2,'u4',ARRAY['K2-1-u4-C7']::text[],'낱말마다 끊어 읽거나 아무 데서나 띄어 읽는다','뜻 덩어리마다 ∨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X08','kor',2,'u4',ARRAY['K2-1-u4-C1','K2-1-u4-C9']::text[],'시를 읽을 때 장면이나 인물의 마음을 떠올리지 않고 글자만 읽는다','눈 감고 장면 그리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X09','kor',2,'u4',ARRAY['K2-1-u4-C1','K2-1-u4-C10','K2-1-u4-C12']::text[],'시의 분위기와 어울리지 않는 목소리나 빠르기로 읽는다','즐거운 시는 밝게, 포근한 시는 부드럽게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X10','kor',2,'u4',ARRAY['K2-1-u4-C8','K2-1-u4-C9']::text[],'한 장면만 보고 인물의 마음을 짐작해 바람을 심술궂다고만 여긴다','끝까지 읽고 행동 전부 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X11','kor',2,'u4',ARRAY['K2-1-u4-C9','K2-1-u4-C12']::text[],'시의 분위기나 느낌에는 정답이 하나뿐이라 친구와 다르면 틀렸다고 여긴다','까닭을 들으면 다 달라도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X12','kor',2,'u4',ARRAY['K2-1-u4-C11']::text[],'시를 바꾸어 쓸 때 원래 시의 틀과 분위기를 무시한다','틀은 두고 내 경험만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X13','kor',2,'u4',ARRAY['K2-1-u4-C12']::text[],'낭송은 크고 빠르게, 긴 시를 읽어야 잘한 것이라 여긴다','장면과 마음이 살아나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X14','kor',2,'u4',ARRAY['K2-1-u4-C12']::text[],'친구의 낭송을 들을 때 흠만 찾거나 딴짓을 한다','끝까지 듣고 칭찬 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X15','kor',2,'u4',ARRAY['K2-1-u4-C13']::text[],'토박이말의 뜻을 헷갈려 문장에 잘못 쓴다','그림과 문장으로 뜻 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
