INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#2','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C6',1,'mc','auto','쓰레기 더미를 만드는 것으로 글에 나온 것은?',ARRAY['K2-1-u4-X06']::text[],false,'{"seq":2,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"쓰레기 더미를 만드는 것으로 글에 나온 것은?","options":[{"t":"그물, 부표","correct":true},{"t":"모래, 조개","mis":"K2-1-u4-X06"},{"t":"나뭇잎","mis":"K2-1-u4-X06"}],"explanation":["그물·부표예요.","125쪽이에요.","글에서 짚어요."],"asset":{"type":"passage","lines":["바다에 많은 플라스틱 쓰레기가 모인 곳이 있다는 말을 들어 본 적이 있나요?","쓰레기 더미는 물고기를 잡거나 기를 때 쓴 그물, 부표 같은 것들이 모여 만들어져요.","함부로 버린 페트병, 물휴지, 과자 봉지가 강을 거쳐 바다로 흘러가 커져요.","환경 단체들은 해안가 쓰레기를 줍거나 떠다니는 쓰레기를 모아 없애기도 해요.","우리도 일회용 플라스틱을 덜 쓰고, 분류해서 버려요.","일상생활에서 우리가 해야 할 몫을 찾아 함께 실천해요."],"title":"『국어』 124~125쪽 「바다에 쓰레기가 모여 있다고?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
