INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#9','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C6',4,'essay','teacher','127쪽 세상과 이어 보기 — 플라스틱 쓰레기 더미를 없애려고 내가 실천할 수 있는 일을 구체적으로 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C6","difficulty":4,"kind":"essay","stem":"127쪽 세상과 이어 보기 — 플라스틱 쓰레기 더미를 없애려고 내가 실천할 수 있는 일을 구체적으로 두 가지 쓰세요.","answer_guide":{"answer":"예: 학교에 텀블러를 가지고 다닌다. 과자 봉지와 페트병을 나누어 분리 배출한다.","scoring_points":["실천할 일을 두 가지 썼어요","구체적이고 할 수 있는 일이에요"]},"explanation":["실천이에요.","127쪽이에요.","지도서 180쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#10','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C7',4,'essay','teacher','「환경 단체들은 해안가에 있는 플라스틱 쓰레기를 줍거나 바다에 떠다니는 쓰레기를 모아 없애기도 해요.」에서 띄어 읽을 곳을 ∨로 나타내 다시 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C7","difficulty":4,"kind":"essay","stem":"「환경 단체들은 해안가에 있는 플라스틱 쓰레기를 줍거나 바다에 떠다니는 쓰레기를 모아 없애기도 해요.」에서 띄어 읽을 곳을 ∨로 나타내 다시 쓰세요.","answer_guide":{"answer":"예: 환경 단체들은 ∨ 해안가에 있는 플라스틱 쓰레기를 줍거나 ∨ 바다에 떠다니는 쓰레기를 모아 ∨ 없애기도 해요.","scoring_points":["뜻 덩어리마다 ∨를 했어요","낱말마다 끊지 않았어요"]},"explanation":["띄어 읽기예요.","126쪽이에요.","지도서 178쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
