INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#24','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C4',4,'essay','teacher','지도서 196~197쪽 평가 — 겹받침이 있는 낱말(많다·넓다·앉다·읽다·값 가운데 둘)을 바르게 넣어 오늘 있었던 일을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u4-C4","difficulty":4,"kind":"essay","stem":"지도서 196~197쪽 평가 — 겹받침이 있는 낱말(많다·넓다·앉다·읽다·값 가운데 둘)을 바르게 넣어 오늘 있었던 일을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 오늘 넓은 운동장에서 친구들과 달리기를 했다. 교실에 돌아와 의자에 앉아 그림책을 읽었다.","scoring_points":["겹받침 낱말을 둘 넣었어요","바른 표기로 썼어요"]},"explanation":["일기 문장이에요.","지도서 197쪽이에요.","평가 자료 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#25','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C12',4,'essay','teacher','지도서 198~199쪽 평가 — 친구들 앞에서 낭송할 시의 제목과 고른 까닭, 어떤 목소리로 낭송할지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C12","difficulty":4,"kind":"essay","stem":"지도서 198~199쪽 평가 — 친구들 앞에서 낭송할 시의 제목과 고른 까닭, 어떤 목소리로 낭송할지를 쓰세요.","answer_guide":{"answer":"예: 「오늘」 — 기분 좋은 하루가 떠올라서 골랐다. 밝고 힘찬 목소리로 조금 빠르게 낭송하겠다.","scoring_points":["시 제목과 고른 까닭을 썼어요","분위기에 맞는 낭송 방법을 썼어요"]},"explanation":["낭송 계획이에요.","지도서 199쪽이에요.","평가 자료 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
