INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#19','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C9',3,'ox','auto','「바람은 착하지」의 바람은 신문지를 구기니까 심술궂기만 하다.',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":19,"concept":"K2-1-u4-C9","difficulty":3,"kind":"ox","stem":"「바람은 착하지」의 바람은 신문지를 구기니까 심술궂기만 하다.","answer":"X","reason_options":[{"t":"끝까지 읽으면 그 신문지로 민들레꽃에게 목도리를 해 주어서","correct":true},{"t":"신문지를 구긴 장면이 가장 중요해서","mis":"K2-1-u4-X10"}],"mis":"K2-1-u4-X10","explanation":["끝까지 읽어요.","129쪽이에요.","행동 전부요."],"asset":{"type":"scene","icon":"🍃","text":"「바람은 착하지」(권영상) — 바람이 신문지를 끌고 골목으로 나가 떠는 민들레꽃에게 목도리를 해 주고 「힘내렴!」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#20','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C13',3,'mc','auto','평가 일기에서 바르게 쓴 낱말끼리 모은 것은?',ARRAY['K2-1-u4-X02']::text[],false,'{"seq":20,"concept":"K2-1-u4-C13","difficulty":3,"kind":"mc","stem":"평가 일기에서 바르게 쓴 낱말끼리 모은 것은?","options":[{"t":"많은 · 몫을 · 값진 · 앉았다","correct":true},{"t":"마는 · 목슬 · 갑찐 · 안잤다","mis":"K2-1-u4-X02"},{"t":"많은 · 목슬 · 값진 · 안잤다","mis":"K2-1-u4-X02"}],"explanation":["바른 표기예요.","지도서 196쪽이에요.","평가예요."],"asset":{"type":"passage","lines":["오늘 학교에서 (많은, 마는) 일이 있었다.","선생님과 함께 (널븐, 넓은) 운동장에 가서 달리기를 했다.","나는 내 (목슬, 몫을) 잘하겠다고 다짐했다.","선생님께서 「열심히 하는 모습이 (값진, 갑찐) 일이다.」라고 하셨다.","교실에 들어와서 의자에 (앉았다, 안잤다).","선생님께서 그림책을 (읽어, 일거) 주셨다."],"title":"지도서 197쪽 평가 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
