INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#23','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C13',4,'sa','auto','우리말에 원래 있던 낱말이나 그것을 활용해 새로 만든 낱말을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u4-C13","difficulty":4,"kind":"sa","stem":"우리말에 원래 있던 낱말이나 그것을 활용해 새로 만든 낱말을 네 글자로 쓰세요.","answer":["토박이말"],"explanation":["토박이말이에요.","142쪽이에요.","도우미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#24','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C6',4,'essay','teacher','플라스틱 쓰레기 더미를 없애려고 내가 실천할 수 있는 일을 구체적으로 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u4-C6","difficulty":4,"kind":"essay","stem":"플라스틱 쓰레기 더미를 없애려고 내가 실천할 수 있는 일을 구체적으로 두 가지 쓰세요.","answer_guide":{"answer":"예: 학교에 텀블러를 가지고 다닌다. 과자 봉지와 페트병을 나누어 분리 배출한다.","scoring_points":["실천할 일을 두 가지 썼어요","구체적인 일이에요"]},"explanation":["실천이에요.","127쪽이에요.","지도서 180쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
